-- tools/smoke/jit_smoke.lua -- M1 2.8: paddle.jit.load + forward inference.
-- Covers 08-jit-infer.md sec.5 acceptance subset: a python-trained export
-- loads, function_names() reports it, forward() is numerically correct,
-- to(place) and clone() work. Full bitwise ResNet18 parity is the M1-G2
-- acceptance (needs the real model asset); this smoke pins the binding.
--
-- Build first:  cmake -S . -B build-test
--               cmake --build build-test --target paddle_core -j 6
-- The export asset is generated by python (paddle.jit.save, OldIrGuard
-- non-PIR); the tiny net is
--   y = relu(x + x + b), b = [0.5]  ->  x = [2,4] all 1.0  ->  2.5
-- Asset lives in tools/smoke/data/jit_export/ (regenerate with
-- tools/smoke/gen_jit_export.py).
--
-- Run (from the repo root):
--   PATH=<paddle runtime dll dirs>;$PATH luajit tools/smoke/jit_smoke.lua
--
-- Lua 5.1 / LuaJIT compatible; matches the 5.1 subset (C3).
--
-- NOTE (Q-25): a New-executor run leaves paddle's async thread pool
-- (GarbageCollector / DeviceKernelLaunch threads, nonblocking_threadpool)
-- winding down; exiting a host lua_State right after forward can
-- 0xC0000005 at teardown (deterministic here, clean with os.exit or a
-- short wait -- see docs/migration/process/open-questions.md Q-25).
-- This is an upstream teardown race, not a binding bug; the smoke ends
-- with os.exit(0) so the exit code reflects the assertions.

package.cpath = "./build-test/?.dll;" .. package.cpath
package.path = "./lua/?.lua;./lua/?/init.lua;" .. package.path

local ok, core = pcall(require, "paddle_core")
assert(ok, "require paddle_core failed: " .. tostring(core))
core.init()

require "paddle.tensor"
local jit = require "paddle.jit"

local cpu = core.pd_place_new(core.PD_PLACE_CPU, 0)
local F32 = core.PD_DTYPE_FLOAT32

-- --- 1: load a python-trained export (paddle.jit.load) -----------------
local layer = jit.load{ path = "tools/smoke/data/jit_export/tiny" }
assert(layer ~= nil, "jit.load returns a layer")

-- --- 2: function_names() reports the saved function -------------------
local names = layer:function_names()
assert(type(names) == "table" and #names == 1, "one function name")
assert(names[1] == "forward", ("function name == 'forward', got %s")
  :format(tostring(names[1])))

-- --- 3: forward is numerically correct: y = relu(x+x+b), x=1 -> 2.5 ----
local x = core.pd_op_full({2, 4}, 1.0, F32, cpu)
local y = layer(x)                      -- __call -> forward
assert(y:ndim() == 2 and y:numel() == 8, "output shape [2,4]")
local v0 = y:item(1)                     -- Lua-side decode, 1-based
assert(math.abs(v0 - 2.5) < 1e-6,
       ("forward(x=1) == 2.5, got %s"):format(v0))

-- --- 4: to(place) is a no-op round trip on CPU ------------------------
layer:to(cpu)
local y2 = layer:forward(x)             -- explicit :forward, same op
assert(math.abs(y2:item(1) - 2.5) < 1e-6, "forward after to(CPU) stable")

-- --- 5: clone() gives an independent instance that also runs -----------
local c = layer:clone()
local y3 = c(x)
assert(math.abs(y3:item(1) - 2.5) < 1e-6, "clone() forward == 2.5")

print("JIT_SMOKE PASS")

-- Q-25: see header note -- teardown race on host lua_State exit.
os.exit(0)
